/**
 * Symbols written by this repository's own Code 128 and EAN/UPC SVG writer, recorded as the SVG text it returned, at
 * module widths 2 and 3: the writer's source at commit 97d3556 (the last commit that changed it; checked at 2026-10-03,
 * repository HEAD aaf9a87). They are committed as text because a tool folder may not import another folder. Each
 * symbol is written with no human readable text and 80 pixel bars.
 *
 * `readText` is what a reader should report, from the GS1 General Specifications and not from the writer: an EAN-13
 * given 12 digits gets the one check digit the mod 10 rule gives (590123412345 -> 5901234123457: the weighted sum
 * 83 gives 7), and UPC-A is an EAN-13 symbol with an implied leading zero, so a UPC-A symbol is read as 13 digits.
 */

export interface RepositoryBarcode {
  name: string;
  /** The reading engine's own name for the symbology the symbol should be read as. */
  format: string;
  /** The data given to the writer. */
  data: string;
  moduleWidth: number;
  /** The text a reader should report. */
  readText: string;
  svg: string;
}

